import{_ as r,o as i,c as e,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Archive Zone- Lessons Learned - Ismael Puerto Freire & Xabier Guitián Domínguez, INDITEX","description":"","frontmatter":{"title":"Archive Zone- Lessons Learned - Ismael Puerto Freire & Xabier Guitián Domínguez, INDITEX","date":"2025-01-23T00:00:00.000Z","updated":"2025-01-24T00:00:00.000Z","tags":["Ceph","Distributed Storage","Archive Storage","Inditex","Storage Architecture"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Archive_Zone_-_Lessons_Learned_-_Ismael_Puerto_Freire_Xabier_Guitian_Dominguez_INDITEX.md","filePath":"posts/2025/Archive_Zone_-_Lessons_Learned_-_Ismael_Puerto_Freire_Xabier_Guitian_Dominguez_INDITEX.md","lastUpdated":1780459816000}'),o={name:"posts/2025/Archive_Zone_-_Lessons_Learned_-_Ismael_Puerto_Freire_Xabier_Guitian_Dominguez_INDITEX.md"};function a(n,l,s,g,u,_){return i(),e("div",null,[...l[0]||(l[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>: Ceph 归档存储集群的使用经验分享<br><strong>会议时间</strong>: 未知<br><strong>主讲人</strong>: Shaban (Inditex) 和 David (系统架构师)<br><strong>参会人员</strong>: Ceph 社区成员及相关技术人员</p><h4 id="_1-公司背景介绍" tabindex="-1">1. <strong>公司背景介绍</strong> <a class="header-anchor" href="#_1-公司背景介绍" aria-label="Permalink to &quot;1. **公司背景介绍**&quot;">​</a></h4><ul><li><strong>Inditex</strong> 是全球知名服装公司，旗下品牌包括 Zara、Massimo Dutti 等，拥有超过 7000 家门店。</li><li>公司在全球范围内运营，需要为不同业务场景提供基础设施支持。</li></ul><h4 id="_2-归档存储的需求与定义" tabindex="-1">2. <strong>归档存储的需求与定义</strong> <a class="header-anchor" href="#_2-归档存储的需求与定义" aria-label="Permalink to &quot;2. **归档存储的需求与定义**&quot;">​</a></h4><ul><li><strong>归档存储</strong>：用于存储不会被删除的历史数据，确保数据在长时间内不会丢失或被意外删除。</li><li><strong>归档集群</strong>：与常规集群不同，归档集群的数据只增不删，用于应对勒索软件等安全事件。</li><li><strong>归档集群的特点</strong>： <ul><li>低性能要求，使用大容量磁盘。</li><li>数据隔离，避免与主集群共享存储。</li><li>用于备份和恢复，确保数据安全。</li></ul></li></ul><h4 id="_3-归档存储集群的架构与挑战" tabindex="-1">3. <strong>归档存储集群的架构与挑战</strong> <a class="header-anchor" href="#_3-归档存储集群的架构与挑战" aria-label="Permalink to &quot;3. **归档存储集群的架构与挑战**&quot;">​</a></h4><ul><li><strong>架构设计</strong>： <ul><li>每个环境（开发、生产等）都使用 <strong>Flash 磁盘</strong>，副本数为 3。</li><li>生产环境启用了归档功能，数据存储在 <strong>S3</strong> 中。</li></ul></li><li><strong>挑战</strong>： <ul><li>初始环境包含 7500 万个对象，数据量庞大。</li><li>需要满足三个主要需求： <ol><li>数据中心外备份，确保高可用性。</li><li>最小化服务数量，保持高密度存储。</li><li>数据复制到总部及两个备份站点（S1 和 S2），延迟为 55ms。</li></ol></li></ul></li></ul><h4 id="_4-硬件选择与配置" tabindex="-1">4. <strong>硬件选择与配置</strong> <a class="header-anchor" href="#_4-硬件选择与配置" aria-label="Permalink to &quot;4. **硬件选择与配置**&quot;">​</a></h4><ul><li>服务器配置： <ul><li>12 块数据磁盘，1 块 NVMe 磁盘用于日志，1 块用于操作系统。</li><li>网络配置：公共网络、集群网络、管理网络。</li></ul></li><li><strong>CRUSH 配置</strong>： <ul><li>使用 <strong>k=4, m=2</strong> 的纠删码配置，平衡性能与容错。</li><li>创建了一个大池，PG 数量为 32。</li></ul></li><li><strong>问题与调整</strong>： <ul><li>初始配置导致 <strong>PG 数量增长过快</strong>，每月增加 34 个 PG。</li><li>发现 <strong>RocksDB</strong> 元数据存储不足，建议 <strong>block.db 大小应为 block 大小的 4%</strong>。</li><li>硬件选择不当，导致性能问题，最终重新设计硬件配置。</li></ul></li></ul><h4 id="_5-归档存储的实现与优化" tabindex="-1">5. <strong>归档存储的实现与优化</strong> <a class="header-anchor" href="#_5-归档存储的实现与优化" aria-label="Permalink to &quot;5. **归档存储的实现与优化**&quot;">​</a></h4><ul><li><strong>归档池的创建</strong>： <ul><li>使用 <code>tier type=archive</code> 创建归档池。</li><li>数据从主集群缓慢迁移到归档集群。</li></ul></li><li><strong>问题与解决方案</strong>： <ul><li><strong>重复对象问题</strong>：发现归档集群中存在重复对象，原因是主集群中的旧版本数据未正确清理。</li><li><strong>OSD 重启问题</strong>：由于大量数据迁移，OSD 频繁重启，调整超时时间后问题缓解。</li><li><strong>RocksDB 性能问题</strong>：通过调整 block.db 大小，解决了元数据存储不足的问题。</li></ul></li></ul><h4 id="_6-归档存储的管理与策略" tabindex="-1">6. <strong>归档存储的管理与策略</strong> <a class="header-anchor" href="#_6-归档存储的管理与策略" aria-label="Permalink to &quot;6. **归档存储的管理与策略**&quot;">​</a></h4><ul><li><strong>生命周期策略</strong>： <ul><li>默认策略：归档数据保留 10 年。</li><li>清理策略：清理主集群中的多版本对象，保留 3 个版本。</li></ul></li><li><strong>垃圾清理</strong>： <ul><li>使用 <code>radosgw</code> 的垃圾清理功能，避免不必要的对象保留。</li><li>创建删除标记（delete marker）以便后续清理。</li></ul></li></ul><h4 id="_7-监控与告警" tabindex="-1">7. <strong>监控与告警</strong> <a class="header-anchor" href="#_7-监控与告警" aria-label="Permalink to &quot;7. **监控与告警**&quot;">​</a></h4><ul><li><strong>监控系统</strong>： <ul><li>使用 <strong>VictoriaMetrics</strong> 收集集群指标。</li><li>关键指标包括： <ul><li><strong>Ceph Manager</strong> 和 <strong>Prometheus Exporter</strong>。</li><li><strong>SPoTman</strong>（容器运行状态）和 <strong>RGW Exporter</strong>（RGW 状态）。</li></ul></li><li>每个集群和环境都有独立的标识，便于告警管理。</li></ul></li></ul><h4 id="_8-未来展望" tabindex="-1">8. <strong>未来展望</strong> <a class="header-anchor" href="#_8-未来展望" aria-label="Permalink to &quot;8. **未来展望**&quot;">​</a></h4><ul><li><strong>多策略归档</strong>： <ul><li>未来计划使用多策略归档，减少不必要的存储占用。</li><li>预计在下一个版本（Squeeze）中实现。</li></ul></li></ul><h4 id="_9-问答环节" tabindex="-1">9. <strong>问答环节</strong> <a class="header-anchor" href="#_9-问答环节" aria-label="Permalink to &quot;9. **问答环节**&quot;">​</a></h4><ul><li><strong>重复对象问题</strong>：问题已解决，未来将简化配置以避免类似问题。</li><li><strong>归档存储的实际收益</strong>： <ul><li>主要用于防止意外删除，特别是存储重要文件（如政府签署的账单）。</li><li>归档存储确保数据在需要时可恢复，避免业务中断。</li></ul></li></ul><h4 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h4><p>Inditex 分享了其在 Ceph 归档存储集群上的实践经验，重点介绍了归档存储的需求、架构设计、硬件选择、问题排查与优化策略。通过生命周期管理和监控系统，Inditex 成功实现了数据的长期保存与安全备份，未来计划进一步优化归档策略，减少存储浪费。</p>',22)])])}const c=r(o,[["render",a]]);export{d as __pageData,c as default};
